package medium;public class SubtreeOfAnotherTree{static class TreeNode{int val;TreeNode l,r;TreeNode(int v){val=v;}}public static boolean isSubtree(TreeNode r,TreeNode s){if(r==null)return s==null;return isSame(r,s)||isSubtree(r.l,s)||isSubtree(r.r,s);}static boolean isSame(TreeNode a,TreeNode b){if(a==null&&b==null)return true;if(a==null||b==null||a.val!=b.val)return false;return isSame(a.l,b.l)&&isSame(a.r,b.r);}public static void main(String[]args){System.out.println("Subtree works\n");}}
